(()=>{
'use strict';
let flow=null;
const api=async(game,token,path,body)=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const r=await fetch('/api/'+game+'/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal});const data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Falha na conexão'),{status:r.status});return data;}finally{clearTimeout(timer);}};
// A peer controls the simulation, but never supplies HTML or card asset metadata.
function peerState(game,value){if(!value||typeof value!=='object'||![0,1].includes(value.you))throw Error('Resposta inválida do anfitrião.');
 if(game==='pokemon'){const card=c=>{const original=PokemonTableData.cards.find(a=>a.id===c?.id);if(!original||!Number.isFinite(c.hp))throw Error('Carta inválida.');return {...original,hp:Math.max(0,Math.min(50,c.hp))};};if(!Array.isArray(value.pool)||!Array.isArray(value.hands)||value.hands.length!==2)throw Error('Partida inválida.');value.pool=value.pool.map(card);value.hands=value.hands.map(h=>h.map(card));if(value.result)value.result.cards=value.result.cards.map(card);}
 else if(!Array.isArray(value.characters)||value.characters.length!==2||value.characters.some(c=>c!==null&&!['bluey','bingo'].includes(c)))throw Error('Personagem inválida.');
 return value;}
class Connection{
 constructor(game,token,level){this.game=game;this.token=token;this.level=level;this.peer=null;this.channel=null;this.pending=new Map();this.next=0;this.closed=false;this.direct=false;this.owner=false;this.engine=null;this.keys=null;this.ticker=0;this.watch=0;}
 http(path,b){return api(this.game,this.token,path,b);}
 initEngine(){if(this.engine)return;const Class=this.game==='pokemon'?PokemonSessions.Matchmaking:KeepupSessions.KeepupMatchmaking;this.engine=new Class();this.keys=[this.engine.join({level:this.level}).token,this.engine.join({level:this.level}).token];this.ticker=setInterval(()=>this.engine.sweep(),20);}
 local(path,b,seat){if(!this.engine)throw Error('Aguardando anfitrião.');if(path==='state')return this.engine.state(this.keys[seat]);if(path==='action')return this.engine.action(this.keys[seat],b);throw Error('Ação inválida.');}
 send(value){if(this.channel?.readyState!=='open'||this.channel.bufferedAmount>262144)throw Error('Conexão direta indisponível.');this.channel.send(JSON.stringify(value));}
 attach(channel){this.channel=channel;channel.onmessage=e=>{if(typeof e.data!=='string'||e.data.length>131072)return;let m;try{m=JSON.parse(e.data);}catch{return;}if(this.owner&&m.kind==='request'&&Number.isSafeInteger(m.id)){let result;try{result={kind:'reply',id:m.id,data:this.local(m.path,m.body,1)};}catch(err){result={kind:'reply',id:m.id,error:err.message,status:err.status||409};}try{this.send(result);}catch{}}else if(!this.owner&&m.kind==='reply'){const p=this.pending.get(m.id);if(p){clearTimeout(p.timer);this.pending.delete(m.id);if(m.error)p.reject(Object.assign(Error(m.error),{status:m.status}));else try{p.resolve(peerState(this.game,m.data));}catch(e){p.reject(e);}}}};channel.onclose=()=>{this.linkLost=true;};}
 async negotiate(owner){this.owner=owner;if(!window.RTCPeerConnection)throw Error('Conexão direta indisponível.');this.peer=new RTCPeerConnection({iceServers:[]});if(owner){this.initEngine();this.attach(this.peer.createDataChannel('alice-isabela',{ordered:true}));await this.peer.setLocalDescription(await this.peer.createOffer());await this.publishSignal();}else this.peer.ondatachannel=e=>this.attach(e.channel);}
 async publishSignal(){const peer=this.peer;if(peer.iceGatheringState!=='complete')await new Promise(resolve=>{const done=()=>{clearTimeout(timer);peer.removeEventListener('icegatheringstatechange',check);resolve();},check=()=>{if(peer.iceGatheringState==='complete')done();},timer=setTimeout(done,1800);peer.addEventListener('icegatheringstatechange',check);});if(this.closed)return;await this.http('action',{kind:'room-signal',signal:{type:peer.localDescription.type,sdp:peer.localDescription.sdp}});}
 async signal(s){if(!s||!this.peer||this.peer.remoteDescription)return;await this.peer.setRemoteDescription(s);if(!this.owner){await this.peer.setLocalDescription(await this.peer.createAnswer());await this.publishSignal();}}
 async request(path,body){if(this.closed||this.linkLost)throw Object.assign(Error('Conexão com o anfitrião encerrada. Volte à sala para jogar.'),{status:401});if(!this.direct)return this.http(path,body);if(this.owner)return JSON.parse(JSON.stringify(this.local(path,body,0)));return new Promise((resolve,reject)=>{const id=++this.next,timer=setTimeout(()=>{this.pending.delete(id);reject(Error('Aguardando anfitrião.'));},2000);this.pending.set(id,{resolve,reject,timer});try{this.send({kind:'request',id,path,body});}catch(e){clearTimeout(timer);this.pending.delete(id);reject(e);}});}
 activateDirect(){this.direct=true;let watching=false;this.watch=setInterval(async()=>{if(watching||this.closed)return;watching=true;try{const s=await this.http('state');if(s.lobby?.closed)this.linkLost=true;}catch(e){if(e.status===401)this.linkLost=true;}finally{watching=false;}},1000);}
 fallback(){clearInterval(this.ticker);this.ticker=0;this.engine=null;if(this.channel)this.channel.onclose=null;this.channel?.close();this.peer?.close();this.channel=null;this.peer=null;this.linkLost=false;}
 close(){if(this.closed)return;this.closed=true;clearInterval(this.watch);clearInterval(this.ticker);this.fallback();for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(Error('Sala encerrada.'));}this.pending.clear();fetch('/api/'+this.game+'/leave',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+this.token},body:'{}',keepalive:true}).catch(()=>{});}
 get label(){return this.direct?(this.owner?'Seu aparelho é o anfitrião · conexão direta':'Conexão direta com o anfitrião'):'Conexão pelo servidor';}
}
function cancel(){if(flow){flow.cancelled=true;clearTimeout(flow.timer);flow.connection?.close();flow=null;}}
function layout(title,text){document.getElementById('app').innerHTML='<section class="online-room"><button id="room-back">← Voltar</button><h1></h1><p class="room-description"></p><div class="room-body"></div><p id="room-status" role="status"></p></section>';document.querySelector('.online-room h1').textContent=title;document.querySelector('.room-description').textContent=text;}
function menu(options){cancel();layout('Jogar com outra pessoa','Procure uma partida ou convide alguém para uma sala só de vocês.');document.querySelector('.room-body').innerHTML='<button id="room-match">Procurar partida</button><button id="room-create">Convidar um amigo</button><label class="room-host"><input id="room-host" type="checkbox" checked> Hospedar no meu aparelho nas salas por convite</label><small>A conexão direta é especialmente útil na mesma rede. Se não funcionar, usaremos o servidor.</small>';if(options.game==='keepup'){const label=document.createElement('label');label.textContent='Dificuldade ';label.innerHTML+='<select id="room-level"><option value="easy">Fácil</option><option value="medium">Médio</option><option value="hard">Difícil</option></select>';document.querySelector('.room-body').prepend(label);const select=label.querySelector('select');select.value=options.level||'easy';select.onchange=()=>{options.level=select.value;options.onLevelChange?.(select.value);};}document.querySelector('#room-back').onclick=options.back;document.querySelector('#room-match').onclick=options.matchmaking;document.querySelector('#room-create').onclick=()=>join(options,{private:true,preferHost:document.querySelector('#room-host').checked,level:options.level});}
async function join(options,body){cancel();const f={options,cancelled:false,timer:0,key:'',connection:null};flow=f;layout('Entrando na sala…','Conectando.');document.querySelector('#room-back').onclick=()=>{cancel();options.back();};try{const data=await api(options.game,null,'join',body);const c=new Connection(options.game,data.token,data.lobby?.level||options.level);if(f.cancelled){c.close();return;}f.connection=c;await accept(f,data);if(!f.cancelled&&flow===f)poll(f);}catch(e){if(!f.cancelled)error(f,e);}}
function error(f,e){const el=document.querySelector('#room-status');if(el)el.textContent=e.message||'Não foi possível conectar.';}
async function accept(f,data){if(f.cancelled)return;const c=f.connection,l=data.lobby;if(!l||l.closed)throw Error(data.reason||'Esta sala foi encerrada.');
 if(data.phase==='lobby'){
  const key=JSON.stringify(l);if(f.key===key)return;f.key=key;layout(l.owner?'Convide seu amigo':'Você entrou na sala',l.owner?(l.full?'Seu amigo chegou! Você já pode começar.':'Compartilhe o link e aguarde seu amigo entrar.'):'Aguardando o anfitrião começar.');document.querySelector('#room-back').onclick=()=>{cancel();f.options.back();};
  const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('game',f.options.game);url.searchParams.set('room',l.code);document.querySelector('.room-body').innerHTML='<label>Link da sala<input id="room-link" readonly aria-label="Link da sala"></label><div><button id="room-share">Compartilhar link</button><button id="room-copy">Copiar link</button></div>'+(l.owner?'<button id="room-start" '+(!l.full?'disabled':'')+'>Começar jogo</button>':'')+'<small>Somente quem tiver este link pode entrar. A sala comporta duas pessoas.</small>';document.querySelector('#room-link').value=url.href;
  const copy=async()=>{try{await navigator.clipboard.writeText(url.href);document.querySelector('#room-status').textContent='Link copiado!';}catch{const input=document.querySelector('#room-link');input.focus();input.select();document.querySelector('#room-status').textContent='Selecione e copie o link acima.';}};
  document.querySelector('#room-copy').onclick=copy;document.querySelector('#room-share').onclick=async()=>{if(!navigator.share)return copy();try{await navigator.share({title:'Vamos jogar juntos?',text:'Entre na minha sala de '+(f.options.game==='pokemon'?'Pokémon':'Bluey e Bingo'),url:url.href});}catch(e){if(e.name!=='AbortError')copy();}};
  const start=document.querySelector('#room-start');if(start)start.onclick=async()=>{start.disabled=true;try{await accept(f,await c.http('action',{kind:'room-start'}));}catch(e){start.disabled=false;error(f,e);}};return;
 }
 if(data.phase==='connecting'){
  if(!f.negotiating){f.negotiating=true;layout('Preparando a conexão direta','Tentando conectar os aparelhos. Se não for possível, a partida usará o servidor.');document.querySelector('#room-back').onclick=()=>{cancel();f.options.back();};try{await c.negotiate(l.owner);}catch{await c.http('action',{kind:'room-fallback'});return;}}
  try{await c.signal(data.signal);if(c.channel?.readyState==='open'&&!f.connected){f.connected=true;await c.http('action',{kind:'room-connected'});}}catch{await c.http('action',{kind:'room-fallback'});}return;
 }
 if(f.launched)return;f.launched=true;
 if(data.phase==='direct'){if(c.channel?.readyState!=='open')throw Error('A conexão direta foi interrompida.');c.activateDirect();}else c.fallback();
 let initial;try{initial=await c.request('state');}catch(e){f.launched=false;throw e;}if(f.cancelled){c.close();return;}clearTimeout(f.timer);flow=null;await f.options.start({token:c.token,state:initial,connection:c});
}
async function poll(f){if(f.cancelled||flow!==f)return;try{await accept(f,await f.connection.http('state'));}catch(e){if(!f.cancelled)error(f,e);}if(!f.cancelled&&flow===f)f.timer=setTimeout(()=>poll(f),400);}
function invitation(options,code){cancel();layout('Convite para jogar '+(options.game==='pokemon'?'Pokémon':'Bluey e Bingo'),'Entre na sala do seu amigo.');document.querySelector('.room-body').innerHTML='<button id="room-enter">Entrar na sala</button>';document.querySelector('#room-back').onclick=options.back;document.querySelector('#room-enter').onclick=()=>join(options,{invite:code});}
window.OnlineRooms={menu,invitation,cancel,Connection};
window.addEventListener('pagehide',cancel);
})();
